import type {
  Analysis,
  AskResponse,
  FileResponse,
  FlowResponse,
  ImpactResponse,
} from "../shared/types";
import { answerQuestion } from "../server/ask";
import { buildFlow, buildImpact } from "../server/flow";
import type { RepoRecord } from "../server/store";

interface StaticSnapshot {
  version: number;
  generatedAt: string;
  analysis: Analysis;
  contents: Record<string, string>;
  parsed: Record<string, { symbols: { id: string; body: string }[] }>;
}

let recordPromise: Promise<RepoRecord> | null = null;

async function loadRecord(): Promise<RepoRecord> {
  if (!recordPromise) {
    recordPromise = (async () => {
      const url = `${import.meta.env.BASE_URL}repo-cloud-static.json`;
      const response = await fetch(url, { cache: "no-cache" });
      if (!response.ok) {
        throw new Error(
          `This Pages build is missing its baked analysis (${response.status}). Run npm run build:pages.`,
        );
      }
      const snapshot = (await response.json()) as StaticSnapshot;
      return {
        analysis: snapshot.analysis,
        contents: new Map(Object.entries(snapshot.contents)),
        parsed: new Map(Object.entries(snapshot.parsed)) as unknown as RepoRecord["parsed"],
      };
    })();
  }
  return recordPromise;
}

function ensureSameRepo(record: RepoRecord, id: string): void {
  if (id && id !== record.analysis.id) {
    throw new Error("The static Pages build contains only one repository snapshot. Reload the page.");
  }
}

export async function analyzeStaticRepo(input: {
  source: "local" | "github";
  path?: string;
  url?: string;
}): Promise<{ analysis: Analysis }> {
  const record = await loadRecord();
  if (input.source === "github") {
    throw new Error(
      "GitHub imports need the Node backend. This GitHub Pages build is a baked self-analysis of The Repo Cloud; run npm run dev for live local or GitHub imports.",
    );
  }
  const requested = (input.path ?? ".").trim();
  if (requested && requested !== "." && requested !== record.analysis.source.path) {
    throw new Error(
      "This GitHub Pages build is a fixed self-analysis. Run npm run dev to analyze another path or a GitHub repository.",
    );
  }
  return { analysis: record.analysis };
}

export async function staticFetchFile(repo: string, filePath: string): Promise<FileResponse> {
  const record = await loadRecord();
  ensureSameRepo(record, repo);
  const content = record.contents.get(filePath);
  const meta = record.analysis.files.find((file) => file.path === filePath);
  if (content === undefined || !meta) throw new Error(`File not in analysis: ${filePath}`);
  return { path: filePath, lang: meta.lang, content };
}

export async function staticAskQuestion(
  repo: string,
  question: string,
  history: Parameters<typeof answerQuestion>[2] = [],
): Promise<AskResponse> {
  const record = await loadRecord();
  ensureSameRepo(record, repo);
  return answerQuestion(record, question, history);
}

export async function staticTraceFlow(
  repo: string,
  payload: { query?: string; symbolId?: string },
): Promise<FlowResponse> {
  const record = await loadRecord();
  ensureSameRepo(record, repo);
  return buildFlow(record, payload);
}

export async function staticAnalyzeImpact(repo: string, symbolId: string): Promise<ImpactResponse> {
  const record = await loadRecord();
  ensureSameRepo(record, repo);
  return buildImpact(record, symbolId);
}

export function staticConfig(): { llm: boolean; model: string } {
  return { llm: false, model: "baked snapshot" };
}

contents.src/styles.css:
:root {
  --ink: #222;
  --paper: #ffffff;
  --paper-2: #fafafa;
  --paper-3: #f2f2f2;
  --bg-top: #ffffff;
  --bg-bottom: #ededed;
  --muted: #6f6f6f;
  --faint: #9a9a9a;
  --yellow: #ffd95e;
  --yellow-soft: #fff3c4;
  --mint: #bfe8d2;
  --salmon: #ffb3ad;
  --blue: #bcd8f7;
  --lilac: #ddd0f4;
  --shadow: 5px 6px 0 -1px var(--ink);
  --shadow-sm: 3px 3px 0 -1px var(--ink);
  --shadow-lg: 8px 10px 0 -2px var(--ink);
  --radius: 14px;
  --mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Courier New", monospace;
  --sans: "Century Gothic", "Futura", "Trebuchet MS", "Segoe UI", system-ui, sans-serif;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
}

body {
  margin: 0;
  color: var(--ink);
  font-family: var(--sans);
  font-size: 14px;
  line-height: 1.5;
  background: linear-gradient(var(--bg-top), var(--bg-bottom));
  background-attachment: fixed;
  -webkit-font-smoothing: antialiased;
}

button,
input,
textarea {
  font: inherit;
  color: var(--ink);
}

button {
  cursor: pointer;
}

button:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}

a {
  color: var(--ink);
  text-decoration: underline;
  text-decoration-thickness: 2px;
  text-underline-offset: 2px;
}

code {
  font-family: var(--mono);
  font-size: 0.9em;
  background: var(--yellow-soft);
  border: 2px solid var(--ink);
  padding: 0 4px;
  border-radius: 6px;
}

::-webkit-scrollbar {
  width: 12px;
  height: 12px;
}
::-webkit-scrollbar-thumb {
  background: #c9c9c9;
  border: 3px solid #fff;
  border-radius: 8px;
}
::-webkit-scrollbar-track {
  background: transparent;
}

.app {
  display: flex;
  flex-direction: column;
  height: 100vh;
  overflow: hidden;
  background:
    radial-gradient(900px 400px at 12% -8%, rgba(255, 217, 94, 0.28), transparent 65%),
    radial-gradient(700px 340px at 94% -4%, rgba(191, 232, 210, 0.4), transparent 62%),
    linear-gradient(var(--bg-top), var(--bg-bottom));
}

.cloud-logo {
  display: block;
  overflow: visible;
}

/* ---------- top bar ---------- */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 12px 22px;
  border-bottom: 3px solid var(--ink);
  background: var(--paper);
  flex-wrap: wrap;
}

.brand {
  display: flex;
  align-items: center;
  gap: 13px;
  min-width: 0;
}

.brand-mark {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border-radius: 12px;
  border: 3px solid var(--ink);
  background: var(--yellow-soft);
  box-shadow: var(--shadow-sm);
  flex: none;
}

.brand-text {
  display: flex;
  flex-direction: column;
  line-height: 1.2;
}

.brand-text strong {
  font-size: 17px;
  letter-spacing: 0.01em;
}

.repo-controls {
  display: flex;
  align-items: center;
  gap: 9px;
  flex-wrap: wrap;
}

.segmented {
  display: flex;
  padding: 3px;
  gap: 3px;
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 12px;
}

.segmented button {
  border: 2px solid transparent;
  background: transparent;
  color: var(--muted);
  padding: 4px 11px;
  border-radius: 8px;
  font-size: 12.5px;
  font-weight: 600;
}

.segmented button.active {
  background: var(--yellow);
  border-color: var(--ink);
  color: var(--ink);
}

.path-input {
  width: 200px;
  padding: 7px 10px;
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 10px;
  font-family: var(--mono);
  font-size: 12px;
  outline: none;
  box-shadow: 2px 2px 0 -1px var(--ink);
}

.path-input.wide {
  width: 300px;
}

.path-input:focus {
  box-shadow: var(--shadow-sm);
  background: var(--yellow-soft);
}

.primary {
  background: var(--yellow);
  border: 3px solid var(--ink);
  padding: 8px 16px;
  border-radius: 11px;
  font-weight: 700;
  font-size: 13px;
  box-shadow: var(--shadow-sm);
  transition: transform 0.08s ease, box-shadow 0.08s ease;
}

.primary:hover:not(:disabled) {
  transform: translate(1px, 1px);
  box-shadow: 2px 2px 0 -1px var(--ink);
}

.primary:active:not(:disabled) {
  transform: translate(3px, 3px);
  box-shadow: none;
}

.ghost {
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 10px;
  padding: 7px 12px;
  font-size: 13px;
  font-weight: 600;
  box-shadow: 2px 2px 0 -1px var(--ink);
  transition: transform 0.08s ease, box-shadow 0.08s ease;
}

.ghost:hover:not(:disabled) {
  background: var(--yellow-soft);
  transform: translate(1px, 1px);
  box-shadow: 1px 1px 0 -1px var(--ink);
}

.ghost.small {
  padding: 5px 10px;
  font-size: 12px;
  border-radius: 9px;
}

.ghost.tiny {
  padding: 2px 8px;
  font-size: 11px;
  box-shadow: none;
}

.ghost-link {
  font-size: 12px;
  font-weight: 600;
  text-decoration-thickness: 2px;
}

.icon-button {
  border: 2px solid transparent;
  background: transparent;
  color: var(--muted);
  width: 28px;
  height: 28px;
  border-radius: 8px;
  display: grid;
  place-items: center;
  flex: none;
  font-size: 13px;
}

.icon-button:hover {
  color: var(--ink);
  border-color: var(--ink);
  background: var(--paper-3);
}

/* ---------- subbar + tabs ---------- */
.subbar {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 9px 22px;
  border-bottom: 2px solid var(--ink);
  background: repeating-linear-gradient(
    135deg,
    var(--paper-2),
    var(--paper-2) 11px,
    #f1f1f1 11px,
    #f1f1f1 12px
  );
  flex-wrap: wrap;
  font-size: 12px;
}

.repo-pill {
  padding: 2px 10px;
  border-radius: 20px;
  border: 2px solid var(--ink);
  background: var(--yellow-soft);
  font-family: var(--mono);
  font-size: 11.5px;
}

.badge {
  padding: 2px 9px;
  border-radius: 20px;
  border: 2px solid var(--ink);
  background: var(--paper);
  font-size: 11.5px;
}

.engine-badge {
  margin-left: auto;
  padding: 2px 10px;
  border-radius: 20px;
  border: 2px solid var(--ink);
  background: var(--mint);
  font-size: 11.5px;
  white-space: nowrap;
  font-weight: 600;
}

.engine-badge.inline {
  margin-left: 0;
}

.tabs {
  display: flex;
  gap: 8px;
  padding: 12px 22px;
  border-bottom: 3px solid var(--ink);
  background: var(--paper);
  overflow-x: auto;
}

.tab {
  border: 2px solid transparent;
  background: transparent;
  color: var(--muted);
  padding: 7px 14px;
  border-radius: 10px;
  font-size: 13px;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 7px;
  white-space: nowrap;
}

.tab:hover {
  color: var(--ink);
  background: var(--paper-3);
}

.tab.active {
  color: var(--ink);
  background: var(--yellow);
  border-color: var(--ink);
  box-shadow: var(--shadow-sm);
}

.tab-count {
  font-size: 10.5px;
  padding: 1px 7px;
  border-radius: 10px;
  background: var(--paper);
  border: 2px solid var(--ink);
  color: var(--ink);
  font-weight: 700;
}

/* ---------- workspace ---------- */
.workspace {
  display: flex;
  flex: 1;
  min-height: 0;
}

.content {
  flex: 1;
  min-width: 0;
  overflow: auto;
  padding: 22px 24px 44px;
}

.tab-panel {
  animation: fade-in 0.18s ease;
}

@keyframes fade-in {
  from {
    opacity: 0;
    transform: translateY(3px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.card {
  background: var(--paper);
  border: 3px solid var(--ink);
  border-radius: var(--radius);
  padding: 18px;
  box-shadow: var(--shadow);
}

.card h3 {
  margin: 0;
  font-size: 14.5px;
  letter-spacing: 0.01em;
}

.section-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 12px;
  border-bottom: 2px dashed #dcdcdc;
  padding-bottom: 8px;
}

.section-head .muted {
  font-size: 11.5px;
}

.muted {
  color: var(--muted);
}

.small-text {
  font-size: 12px;
}

.empty {
  color: var(--muted);
  font-size: 13px;
  margin: 8px 0 0;
}

.eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 10.5px;
  margin: 0 0 6px;
  font-weight: 700;
  color: #6b5a1d;
}

/* ---------- overview ---------- */
.overview {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.hero {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 24px;
  background:
    repeating-linear-gradient(135deg, #fff, #fff 12px, #f4f4f4 12px, #f4f4f4 14px);
  border-width: 4px;
  box-shadow: var(--shadow-lg);
  flex-wrap: wrap;
}

.hero h2 {
  margin: 0 0 6px;
  font-size: 28px;
  letter-spacing: -0.01em;
}

.hero .lede {
  margin: 0;
  color: #3d3d3d;
  font-size: 14px;
}

.hero .small-text {
  margin: 6px 0 0;
  font-family: var(--mono);
  font-size: 11.5px;
  color: var(--muted);
}

.hero-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.stat-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(145px, 1fr));
  gap: 12px;
}

.stat {
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  box-shadow: var(--shadow-sm);
  border-top: 8px solid var(--yellow);
}

.stat:nth-child(2) {
  border-top-color: var(--mint);
}
.stat:nth-child(3) {
  border-top-color: var(--blue);
}
.stat:nth-child(4) {
  border-top-color: var(--salmon);
}
.stat:nth-child(5) {
  border-top-color: var(--lilac);
}
.stat:nth-child(6) {
  border-top-color: #ddd;
}

.stat-value {
  font-size: 24px;
  font-weight: 700;
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
}

.stat-label {
  color: var(--muted);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.09em;
}

.two-col {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(360px, 1fr));
  gap: 18px;
}

.list {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.list-row {
  display: flex;
  flex-direction: column;
  gap: 2px;
  text-align: left;
  padding: 9px 10px;
  border-radius: 9px;
  border: 2px solid transparent;
  background: transparent;
  min-width: 0;
}

.list-row:hover {
  background: var(--yellow-soft);
  border-color: var(--ink);
}

.row-title {
  font-family: var(--mono);
  font-size: 12.5px;
  color: var(--ink);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.row-sub {
  font-size: 11.5px;
  color: var(--muted);
  overflow: hidden;
  text-overflow: ellipsis;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.lang-bars {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.lang-row {
  display: grid;
  grid-template-columns: 86px 1fr 48px;
  align-items: center;
  gap: 10px;
  font-size: 12px;
}

.lang-name {
  color: var(--muted);
}

.bar {
  height: 12px;
  background: var(--paper-3);
  border: 2px solid var(--ink);
  border-radius: 8px;
  overflow: hidden;
}

.bar-fill {
  display: block;
  height: 100%;
  border-right: 2px solid var(--ink);
}

.lang-value {
  text-align: right;
  font-family: var(--mono);
  font-size: 11.5px;
  color: var(--muted);
}

.commit-list {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.commit {
  display: grid;
  grid-template-columns: 70px 1fr auto;
  gap: 12px;
  align-items: baseline;
  padding: 9px 6px;
  border-bottom: 2px dashed #e2e2e2;
  font-size: 12.5px;
}

button.commit {
  width: 100%;
  text-align: left;
  color: var(--ink);
  background: transparent;
  border: 0;
  border-bottom: 2px dashed #e2e2e2;
  border-radius: 0;
  font: inherit;
  font-size: 12.5px;
  cursor: pointer;
}

button.commit:hover:not(:disabled) {
  background: var(--yellow-soft);
}

button.commit.current {
  background: var(--yellow-soft);
}

button.commit:disabled {
  cursor: default;
  opacity: 0.72;
}

.commit:last-child {
  border-bottom: 0;
}

.commit-hash {
  font-family: var(--mono);
  font-size: 11px;
  background: var(--yellow);
  border: 2px solid var(--ink);
  border-radius: 5px;
  padding: 0 5px;
  justify-self: start;
}

.commit-subject {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.commit-meta {
  color: var(--faint);
  font-size: 11px;
  white-space: nowrap;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 3px;
}

.commit-action {
  padding: 0 5px;
  border: 2px solid var(--ink);
  border-radius: 5px;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--mono);
  font-size: 10px;
  line-height: 1.5;
}

button.commit:hover:not(:disabled) .commit-action {
  background: var(--yellow);
}

.snapshot-badge {
  background: var(--yellow-soft);
  font-family: var(--mono);
}

.link-button {
  padding: 0;
  border: 0;
  background: none;
  color: var(--ink);
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  text-decoration: underline;
  text-decoration-thickness: 2px;
  cursor: pointer;
}

.link-button:disabled {
  cursor: default;
  opacity: 0.55;
}

.notes ul {
  margin: 0;
  padding-left: 20px;
  color: var(--muted);
  font-size: 12.5px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

/* ---------- map + graph ---------- */
.map-view {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.ask-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  flex-wrap: wrap;
}

.ask-head.compact {
  align-items: center;
}

.ask-head h2 {
  margin: 0 0 4px;
  font-size: 22px;
}

.ask-head p {
  margin: 0;
  font-size: 12.5px;
  max-width: 720px;
}

.highlight-banner {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 4px 6px 4px 12px;
  border-radius: 20px;
  border: 2px solid var(--ink);
  background: var(--yellow);
  font-size: 12px;
  font-weight: 600;
  box-shadow: 2px 2px 0 -1px var(--ink);
}

.map-body {
  position: relative;
}

.graph-shell {
  position: relative;
  height: calc(100vh - 300px);
  min-height: 460px;
  border: 4px solid var(--ink);
  border-radius: var(--radius);
  background-color: #fff;
  background-image: radial-gradient(#dcdcdc 1.2px, transparent 1.2px);
  background-size: 20px 20px;
  box-shadow: var(--shadow-lg);
  overflow: hidden;
}

.graph-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 12px;
  border-bottom: 2px dashed #c9c9c9;
  flex-wrap: wrap;
  background: rgba(255, 255, 255, 0.92);
}

.legend {
  display: flex;
  gap: 5px;
  flex-wrap: wrap;
}

.legend-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 9px;
  border-radius: 20px;
  border: 2px solid var(--ink);
  background: var(--paper);
  font-size: 11.5px;
  font-weight: 600;
}

.legend-item.active {
  background: var(--yellow);
  box-shadow: 2px 2px 0 -1px var(--ink);
}

.legend-item .dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  display: inline-block;
  border: 1.5px solid var(--ink);
}

.legend-item .count {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 10.5px;
}

.zoom-controls {
  display: flex;
  gap: 5px;
}

.zoom-controls button {
  min-width: 32px;
  padding: 3px 8px;
  font-size: 12px;
  box-shadow: none;
}

.graph-svg {
  width: 100%;
  height: calc(100% - 96px);
  display: block;
  touch-action: none;
  cursor: grab;
}

.graph-svg:active {
  cursor: grabbing;
}

.graph-link {
  stroke: #c9c9c9;
  stroke-width: 1.4;
}

.graph-link.active {
  stroke: var(--ink);
  stroke-width: 2.2;
}

.purpose-cluster {
  pointer-events: none;
}

.purpose-label-bg {
  fill: var(--paper);
  stroke: var(--ink);
  stroke-width: 1.6px;
}

.purpose-label {
  fill: var(--ink);
  font-family: var(--mono);
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-anchor: middle;
}

.purpose-count {
  fill: var(--muted);
  font-size: 10px;
  letter-spacing: 0;
}

.ghost.tiny.active {
  background: var(--yellow);
  box-shadow: 2px 2px 0 -1px var(--ink);
}

.graph-node {
  cursor: pointer;
}

.graph-node circle {
  stroke: #fff;
  stroke-width: 2;
  transition: fill-opacity 0.15s ease;
}

.graph-node:hover circle {
  fill-opacity: 1;
}

.graph-node.selected circle {
  stroke: var(--ink);
  stroke-width: 3;
}

.graph-node.dim {
  opacity: 0.25;
}

.graph-label {
  fill: var(--ink);
  font-size: 10px;
  font-family: var(--mono);
  font-weight: 600;
  text-anchor: middle;
  pointer-events: none;
  paint-order: stroke;
  stroke: #fff;
  stroke-width: 3.5px;
}

.graph-node.selected .graph-label {
  font-size: 11px;
}

.graph-foot {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 14px;
  border-top: 2px dashed #c9c9c9;
  color: var(--muted);
  font-size: 11px;
  background: rgba(255, 255, 255, 0.94);
  flex-wrap: wrap;
}

.graph-hover {
  position: absolute;
  left: 16px;
  bottom: 48px;
  max-width: 380px;
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 10px 12px;
  border-radius: 10px;
  border: 3px solid var(--ink);
  background: #fff;
  pointer-events: none;
  box-shadow: var(--shadow);
}

.graph-hover strong {
  font-family: var(--mono);
  font-size: 12px;
}

.graph-hover span {
  color: var(--muted);
  font-size: 11.5px;
  line-height: 1.45;
}

.impact-card {
  position: absolute;
  top: 16px;
  right: 16px;
  width: min(370px, 90%);
  max-height: calc(100% - 32px);
  overflow: auto;
  background: #fff;
  border-width: 3px;
  box-shadow: var(--shadow-lg);
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.impact-card h3 {
  margin: 0;
  font-family: var(--mono);
  font-size: 14px;
}

.impact-card p {
  margin: 0;
  font-size: 12.5px;
  color: #3d3d3d;
  line-height: 1.55;
}

.impact-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 8px;
}

.impact-section {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.impact-label {
  font-size: 10.5px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--muted);
  font-weight: 700;
}

.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 7px;
  border-radius: 6px;
  background: var(--paper-2);
  border: 2px solid var(--ink);
  color: #3d3d3d;
  font-size: 11px;
  font-family: var(--mono);
}

.chip.accent {
  background: var(--mint);
  color: var(--ink);
}

.chip.clickable {
  cursor: pointer;
}

.chip.clickable:hover {
  background: var(--yellow);
}

/* ---------- code panel ---------- */
.code-panel {
  width: min(560px, 46vw);
  border-left: 3px solid var(--ink);
  background: #fff;
  display: flex;
  flex-direction: column;
  min-height: 0;
  animation: slide-in 0.18s ease;
}

@keyframes slide-in {
  from {
    transform: translateX(14px);
    opacity: 0;
  }
  to {
    transform: none;
    opacity: 1;
  }
}

.code-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 10px;
  padding: 16px 16px 10px;
  border-bottom: 2px dashed #dcdcdc;
  background: repeating-linear-gradient(
    135deg,
    #fff,
    #fff 11px,
    #f7f7f7 11px,
    #f7f7f7 12px
  );
}

.code-head h3 {
  margin: 0;
  font-family: var(--mono);
  font-size: 13px;
  word-break: break-all;
  line-height: 1.4;
}

.code-summary {
  margin: 6px 0 0;
  font-size: 11.5px;
  color: var(--muted);
  line-height: 1.45;
}

.code-meta {
  display: flex;
  gap: 5px;
  flex-wrap: wrap;
  padding: 10px 16px;
}

.code-actions {
  display: flex;
  gap: 6px;
  padding: 0 16px 10px;
  flex-wrap: wrap;
}

.active-symbol {
  margin: 0 16px 10px;
  padding: 7px 10px;
  border-radius: 9px;
  background: var(--yellow-soft);
  border: 2px solid var(--ink);
  font-size: 11.5px;
}

.active-symbol strong {
  font-family: var(--mono);
}

.endpoint-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 0 12px 8px;
}

.endpoint {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 6px;
  border-radius: 7px;
  border: 2px solid transparent;
  background: transparent;
  text-align: left;
}

.endpoint:hover {
  background: var(--paper-3);
  border-color: var(--ink);
}

.method {
  font-family: var(--mono);
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.04em;
  padding: 1px 5px;
  border-radius: 4px;
  color: var(--ink);
  background: #e2e2e2;
  border: 1.5px solid var(--ink);
  min-width: 42px;
  text-align: center;
}

.method-get {
  background: var(--mint);
}
.method-post {
  background: var(--blue);
}
.method-put,
.method-patch {
  background: var(--yellow);
}
.method-delete {
  background: var(--salmon);
}
.method-any {
  background: var(--lilac);
}

.endpoint-path {
  font-family: var(--mono);
  font-size: 11.5px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.endpoint-line {
  margin-left: auto;
  color: var(--faint);
  font-family: var(--mono);
  font-size: 10.5px;
}

.symbol-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  padding: 0 16px 12px;
  max-height: 106px;
  overflow: auto;
}

.symbol-chip {
  padding: 2px 8px;
  border-radius: 6px;
  border: 2px solid var(--ink);
  background: var(--paper);
  color: #3d3d3d;
  font-family: var(--mono);
  font-size: 11px;
}

.symbol-chip:hover,
.symbol-chip.active {
  background: var(--yellow);
  color: var(--ink);
  box-shadow: 2px 2px 0 -1px var(--ink);
}

.code-body {
  flex: 1;
  overflow: auto;
  border-top: 3px solid var(--ink);
  padding: 8px 0 30px;
  background: #fff;
  font-family: var(--mono);
  font-size: 12px;
  line-height: 1.55;
}

.code-line {
  display: flex;
  gap: 12px;
  padding: 0 14px;
  white-space: pre;
  min-width: max-content;
}

.code-line .ln {
  color: #b5b5b5;
  min-width: 44px;
  text-align: right;
  user-select: none;
  flex: none;
}

.code-line .src {
  color: #2b2b2b;
  white-space: pre;
}

.code-line.in-symbol {
  background: rgba(255, 217, 94, 0.2);
}

.code-line.hit {
  background: var(--yellow);
  box-shadow: inset 4px 0 0 var(--ink);
}

.code-line.hit .src {
  color: var(--ink);
}

.code-placeholder {
  padding: 20px 16px;
  color: var(--muted);
  font-family: var(--sans);
  font-size: 12.5px;
}

.code-placeholder.error {
  color: #a12d24;
}

/* ---------- ask ---------- */
.ask-view {
  display: flex;
  flex-direction: column;
  gap: 14px;
  height: calc(100vh - 256px);
  min-height: 440px;
}

.chat {
  flex: 1;
  overflow: auto;
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 4px 4px 10px;
}

.bubble-row {
  display: flex;
  gap: 10px;
  max-width: 920px;
}

.bubble-row.user {
  align-self: flex-end;
  justify-content: flex-end;
}

.bubble {
  padding: 12px 15px;
  border-radius: 14px;
  border: 3px solid var(--ink);
  background: #fff;
  font-size: 13px;
  min-width: 0;
  overflow-wrap: anywhere;
  box-shadow: var(--shadow-sm);
}

.bubble.user {
  background: repeating-linear-gradient(135deg, #fff, #fff 10px, #eee 10px, #eee 12px);
}

.bubble.error {
  border-color: #a12d24;
  background: #fff0ee;
}

.bubble.thinking {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--muted);
  font-size: 12.5px;
  box-shadow: 2px 2px 0 -1px var(--ink);
}

.avatar {
  width: 30px;
  height: 30px;
  flex: none;
  border-radius: 9px;
  display: grid;
  place-items: center;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.04em;
  background: var(--yellow);
  border: 2px solid var(--ink);
  box-shadow: 2px 2px 0 -1px var(--ink);
}

.pulse {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--ink);
  animation: pulse 1s infinite ease-in-out;
}

@keyframes pulse {
  0%,
  100% {
    opacity: 0.25;
    transform: scale(0.85);
  }
  50% {
    opacity: 1;
    transform: scale(1.1);
  }
}

.markdown p {
  margin: 0 0 8px;
  line-height: 1.6;
}

.markdown p:last-child {
  margin-bottom: 0;
}

.markdown ul,
.markdown ol {
  margin: 0 0 8px;
  padding-left: 20px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.markdown li {
  line-height: 1.55;
}

.markdown h4 {
  margin: 10px 0 6px;
  font-size: 13px;
}

.markdown em {
  font-style: normal;
  color: var(--muted);
  font-size: 12px;
}

.cite {
  display: inline-flex;
  align-items: center;
  padding: 0 5px;
  margin: 0 2px;
  border-radius: 5px;
  border: 2px solid var(--ink);
  background: var(--mint);
  color: var(--ink);
  font-family: var(--mono);
  font-size: 10px;
  line-height: 1.55;
  vertical-align: baseline;
  white-space: nowrap;
}

.cite:hover {
  background: var(--yellow);
}

.citations {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 5px;
  margin-top: 10px;
  padding-top: 10px;
  border-top: 2px dashed #dcdcdc;
}

.citations-label {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--muted);
  margin-right: 3px;
  font-weight: 700;
}

.topic-builder {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  padding: 8px 11px;
  border: 2px dashed var(--ink);
  border-radius: 13px;
  background: var(--paper-2);
}

.topic-builder-text {
  font-family: var(--mono);
  font-size: 11.5px;
  font-weight: 700;
  white-space: nowrap;
}

.topic-builder select {
  flex: 1 1 260px;
  min-width: 0;
  max-width: min(100%, 520px);
  padding: 7px 10px;
  border: 2px solid var(--ink);
  border-radius: 9px;
  background: #fff;
  color: var(--ink);
  font-family: var(--mono);
  font-size: 11.5px;
  outline: none;
  box-shadow: 2px 2px 0 -1px var(--ink);
  text-overflow: ellipsis;
}

.topic-builder select:focus {
  background: var(--yellow-soft);
}

.topic-builder select:disabled {
  opacity: 0.58;
  box-shadow: none;
}

.composer {
  display: flex;
  gap: 8px;
  align-items: flex-end;
  padding: 10px;
  border: 3px solid var(--ink);
  border-radius: 14px;
  background: #fff;
  box-shadow: var(--shadow-sm);
}

.composer textarea {
  flex: 1;
  resize: none;
  background: transparent;
  border: 0;
  outline: none;
  font-size: 13px;
  line-height: 1.5;
  padding: 4px 6px;
  min-height: 44px;
  color: var(--ink);
}

.composer textarea::placeholder {
  color: var(--faint);
}

/* ---------- flows ---------- */
.flow-view {
  display: flex;
  flex-direction: column;
  gap: 16px;
  max-width: 1080px;
}

.flow-form {
  display: flex;
  gap: 8px;
}

.flow-form input {
  flex: 1;
  padding: 10px 14px;
  border-radius: 11px;
  border: 3px solid var(--ink);
  background: #fff;
  outline: none;
  font-size: 13.5px;
  box-shadow: var(--shadow-sm);
}

.flow-form input:focus {
  background: var(--yellow-soft);
}

.inline-error {
  padding: 10px 12px;
  border-radius: 10px;
  border: 2px solid #a12d24;
  background: #fff0ee;
  color: #8c241c;
  font-size: 12.5px;
}

.flow-result {
  padding: 20px;
  box-shadow: var(--shadow-lg);
}

.flow-result-head {
  display: flex;
  justify-content: space-between;
  gap: 22px;
  align-items: flex-start;
  flex-wrap: wrap;
  margin-bottom: 16px;
}

.flow-result-head h3 {
  font-size: 19px;
  margin-bottom: 4px;
}

.flow-result-head p {
  margin: 4px 0 0;
  font-size: 12px;
  max-width: 620px;
}

.flow {
  list-style: none;
  padding: 0;
  margin: 0 0 0 15px;
  display: flex;
  flex-direction: column;
  gap: 3px;
  border-left: 3px dashed #c9c9c9;
  padding-left: 16px;
}

.flow-step {
  position: relative;
}

.flow-step::before {
  content: "";
  position: absolute;
  left: -20px;
  top: 22px;
  width: 12px;
  height: 2px;
  background: var(--ink);
}

.flow-button {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  width: 100%;
  text-align: left;
  background: transparent;
  border: 2px solid transparent;
  border-radius: 10px;
  padding: 7px 9px;
}

.flow-button:hover {
  background: var(--yellow-soft);
  border-color: var(--ink);
}

.flow-index {
  width: 26px;
  height: 26px;
  flex: none;
  border-radius: 8px;
  display: grid;
  place-items: center;
  font-size: 11px;
  font-family: var(--mono);
  font-weight: 700;
  background: var(--yellow);
  border: 2px solid var(--ink);
}

.flow-body {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.flow-name {
  display: flex;
  align-items: center;
  gap: 7px;
  font-family: var(--mono);
  font-size: 12.5px;
  flex-wrap: wrap;
}

.flow-file {
  font-size: 11px;
  color: var(--muted);
  font-family: var(--mono);
  overflow-wrap: anywhere;
}

.kind {
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 0 5px;
  border-radius: 4px;
  border: 1.5px solid var(--ink);
  background: #eee;
  font-family: var(--sans);
  font-weight: 700;
}

.kind-endpoint {
  background: var(--mint);
}

.kind-handler {
  background: var(--yellow);
}

.kind-class {
  background: var(--lilac);
}

.flow-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 18px;
  flex-wrap: wrap;
}

/* ---------- debt ---------- */
.debt {
  display: flex;
  flex-direction: column;
  gap: 16px;
  max-width: 1000px;
}

.debt-counts {
  display: flex;
  gap: 7px;
  flex-wrap: wrap;
}

.severity {
  display: inline-flex;
  align-items: center;
  padding: 1px 9px;
  border-radius: 20px;
  font-size: 10.5px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  border: 2px solid var(--ink);
  background: #eee;
  font-weight: 700;
}

.severity.high {
  background: var(--salmon);
}

.severity.medium {
  background: var(--yellow);
}

.severity.low {
  background: #e6e6e6;
}

.issue-card {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.issue-head {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.issue-kind {
  font-size: 11px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-weight: 700;
}

.issue-file {
  margin-left: auto;
  font-family: var(--mono);
  font-size: 11px;
  color: var(--muted);
}

.issue-card h3 {
  font-size: 16px;
}

.issue-card p {
  margin: 0;
  color: #3d3d3d;
  font-size: 12.5px;
  line-height: 1.6;
  max-width: 88ch;
}

.issue-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  margin-top: 4px;
}

.evidence {
  display: flex;
  gap: 5px;
  flex-wrap: wrap;
}

.empty-card {
  color: var(--muted);
  text-align: center;
  padding: 40px;
  box-shadow: var(--shadow-sm);
}

/* ---------- loading + misc ---------- */
.loading-screen {
  min-height: 420px;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 34px;
  padding: 40px;
  flex-wrap: wrap;
}

.loading-figure {
  flex: none;
  filter: drop-shadow(0 3px 0 rgba(34, 34, 34, 0.12));
  animation: cloud-bob 2.4s ease-in-out infinite;
}

@keyframes cloud-bob {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-6px);
  }
}

.loading-bubble {
  position: relative;
  max-width: 470px;
  padding: 26px 28px;
  border: 4px solid var(--ink);
  border-radius: 16px;
  background: repeating-linear-gradient(135deg, #fff, #fff 10px, #eee 10px, #eee 12px);
  box-shadow: var(--shadow-lg);
}

.loading-bubble::before {
  content: "";
  position: absolute;
  left: -17px;
  top: 58px;
  width: 20px;
  height: 20px;
  background: #fff;
  border-left: 4px solid var(--ink);
  border-bottom: 4px solid var(--ink);
  transform: rotate(45deg);
}

.loading-bubble h2 {
  margin: 0 0 8px;
  font-size: 21px;
}

.loading-bubble p {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.6;
}

.loading-bar {
  margin-top: 18px;
  height: 14px;
  border: 2px solid var(--ink);
  border-radius: 8px;
  background: #fff;
  overflow: hidden;
}

.loading-bar span {
  display: block;
  height: 100%;
  width: 40%;
  background: repeating-linear-gradient(
    135deg,
    var(--yellow),
    var(--yellow) 8px,
    #fff 8px,
    #fff 16px
  );
  border-right: 2px solid var(--ink);
  animation: loading-slide 1.1s ease-in-out infinite alternate;
}

@keyframes loading-slide {
  from {
    transform: translateX(-10%);
  }
  to {
    transform: translateX(160%);
  }
}

.spinner {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 3px solid #ddd;
  border-top-color: var(--ink);
  animation: spin 0.9s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

.toast {
  position: fixed;
  bottom: 22px;
  right: 22px;
  max-width: 460px;
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 12px 14px;
  border-radius: 12px;
  border: 3px solid var(--ink);
  border-left-width: 10px;
  background: #fff;
  color: var(--ink);
  font-size: 12.5px;
  box-shadow: var(--shadow-lg);
  z-index: 50;
}

@media (max-width: 1200px) {
  .code-panel {
    width: min(500px, 50vw);
  }
}

@media (max-width: 1000px) {
  .code-panel {
    position: fixed;
    right: 0;
    top: 0;
    bottom: 0;
    width: min(560px, 92vw);
    z-index: 40;
    box-shadow: -10px 0 0 -2px rgba(34, 34, 34, 0.2);
  }
  .graph-shell {
    height: calc(100vh - 286px);
  }
  .commit {
    grid-template-columns: 66px 1fr;
  }
  .commit-meta {
    grid-column: 2;
    white-space: normal;
  }
}

@media (max-width: 720px) {
  .topbar {
    padding: 10px 14px;
  }
  .repo-controls {
    width: 100%;
  }
  .path-input,
  .path-input.wide {
    flex: 1;
    width: auto;
    min-width: 0;
  }
  .subbar,
  .tabs {
    padding-left: 14px;
    padding-right: 14px;
  }
  .content {
    padding: 16px 14px 40px;
  }
  .hero {
    padding: 20px;
  }
  .hero h2 {
    font-size: 22px;
  }
  .engine-badge {
    margin-left: 0;
  }
  .ask-view {
    height: auto;
    min-height: 60vh;
  }
  .loading-screen {
    flex-direction: column;
    gap: 18px;
    padding: 24px 16px;
  }
  .loading-bubble::before {
    left: 50%;
    top: -17px;
    transform: translateX(-50%) rotate(135deg);
  }
  .loading-figure svg {
    width: 92px;
    height: auto;
  }
  .graph-shell {
    height: 520px;
  }
}

contents.src/theme.css:
/*
 * Theme + new-surface styles. Loaded after styles.css so these rules win without
 * rewriting the original hand-drawn sheet. Light mode stays exactly as designed.
 */

:root {
  --on-accent: #222;
  --line: #dcdcdc;
  --line-strong: #c9c9c9;
  --stripe-a: #ffffff;
  --stripe-b: #eeeeee;
  --grid: #dcdcdc;
  --glass: rgba(255, 255, 255, 0.92);
  --halo: #ffffff;
  --code-text: #2b2b2b;
  --severity-low: #e6e6e6;
}

/* Text that sits on a bright accent chip (yellow, mint, salmon). */
.primary,
.segmented button.active,
.tab.active,
.commit-hash,
.avatar,
.flow-index,
.method-put,
.method-patch,
.kind-handler,
.severity.medium,
.highlight-banner,
.legend-item.active {
  color: var(--on-accent);
}

.cloud-logo {
  color: var(--ink);
}

.cloud-logo-eye,
.cloud-logo-mouth {
  fill: var(--paper);
}

/* ---------- theme toggle ---------- */
.theme-toggle {
  width: 34px;
  height: 34px;
  flex: none;
  display: grid;
  place-items: center;
  border: 2px solid var(--ink);
  border-radius: 10px;
  background: var(--paper);
  color: var(--ink);
  font-size: 15px;
  line-height: 1;
  box-shadow: 2px 2px 0 -1px var(--ink);
}

.theme-toggle:hover {
  background: var(--yellow-soft);
}

.examples-button {
  white-space: nowrap;
}

/* ---------- example picker ---------- */
.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 60;
  display: grid;
  place-items: center;
  padding: 24px;
  background: rgba(20, 20, 22, 0.45);
  backdrop-filter: blur(3px);
  animation: fade-in 0.15s ease;
}

.example-modal {
  width: min(880px, 100%);
  max-height: min(86vh, 780px);
  overflow: auto;
  padding: 22px;
  background: var(--paper);
  border: 4px solid var(--ink);
  border-radius: 18px;
  box-shadow: var(--shadow-lg);
}

.example-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
  margin-bottom: 16px;
}

.example-head h2 {
  margin: 0 0 4px;
  font-size: 23px;
}

.example-head p {
  margin: 0;
  max-width: 600px;
  color: var(--muted);
  font-size: 12.5px;
  line-height: 1.55;
}

.example-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 12px;
}

.example-card {
  display: flex;
  flex-direction: column;
  gap: 7px;
  padding: 14px;
  text-align: left;
  background: var(--paper-2);
  border: 3px solid var(--ink);
  border-radius: 12px;
  box-shadow: var(--shadow-sm);
  transition: transform 0.08s ease, box-shadow 0.08s ease, background 0.08s ease;
}

.example-card:hover:not(:disabled) {
  transform: translate(1px, 1px);
  box-shadow: 2px 2px 0 -1px var(--ink);
  background: var(--yellow-soft);
}

.example-top {
  display: flex;
  align-items: center;
  gap: 8px;
}

.example-dot {
  width: 12px;
  height: 12px;
  flex: none;
  border: 2px solid var(--ink);
  border-radius: 50%;
}

.example-name {
  font-size: 14px;
  font-weight: 700;
}

.example-tag {
  margin-left: auto;
  padding: 1px 7px;
  border: 2px solid var(--ink);
  border-radius: 20px;
  background: var(--mint);
  color: var(--ink);
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.example-repo {
  font-family: var(--mono);
  font-size: 11px;
  color: var(--muted);
}

.example-blurb {
  flex: 1;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.5;
}

.example-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-top: 4px;
  padding-top: 8px;
  border-top: 2px dashed var(--line);
  color: var(--muted);
  font-size: 11px;
}

.example-foot strong {
  color: var(--ink);
  font-size: 11.5px;
}

.example-note {
  margin: 16px 2px 0;
  color: var(--muted);
  font-size: 11.5px;
  line-height: 1.5;
}

.example-note code {
  font-size: 10.5px;
}

/* ---------- dark theme ---------- */
[data-theme="dark"] {
  color-scheme: dark;
  --ink: #ece7db;
  --paper: #17181b;
  --paper-2: #1c1e21;
  --paper-3: #26292d;
  --bg-top: #1b1d20;
  --bg-bottom: #101113;
  --muted: #a7a29a;
  --faint: #7e7a72;
  --yellow: #e9c45a;
  --yellow-soft: #332d1e;
  --mint: #2f4a3d;
  --salmon: #4a2f2c;
  --blue: #2a3b50;
  --lilac: #3a3250;
  --line: #33363a;
  --line-strong: #41454a;
  --stripe-a: #1c1e21;
  --stripe-b: #23262a;
  --grid: #2c2f33;
  --glass: rgba(23, 24, 27, 0.92);
  --halo: #17181b;
  --code-text: #ddd8cc;
  --severity-low: #2c2f33;
  --on-accent: #1b1b1b;
}

[data-theme="dark"] .hero {
  background: repeating-linear-gradient(
    135deg,
    var(--stripe-a),
    var(--stripe-a) 12px,
    var(--stripe-b) 12px,
    var(--stripe-b) 14px
  );
}

[data-theme="dark"] .subbar,
[data-theme="dark"] .code-head {
  background: repeating-linear-gradient(
    135deg,
    var(--stripe-a),
    var(--stripe-a) 11px,
    var(--stripe-b) 11px,
    var(--stripe-b) 12px
  );
}

[data-theme="dark"] .hero .lede {
  color: var(--muted);
}

[data-theme="dark"] .eyebrow {
  color: #d8b45c;
}

[data-theme="dark"] .section-head,
[data-theme="dark"] .citations,
[data-theme="dark"] .code-head {
  border-bottom-color: var(--line);
}

[data-theme="dark"] .commit {
  border-bottom-color: var(--line);
}

[data-theme="dark"] .stat:nth-child(6) {
  border-top-color: var(--line);
}

[data-theme="dark"] .graph-shell {
  background-color: var(--paper);
  background-image: radial-gradient(var(--grid) 1.2px, transparent 1.2px);
}

[data-theme="dark"] .graph-toolbar,
[data-theme="dark"] .graph-foot {
  background: var(--glass);
  border-color: var(--line-strong);
}

[data-theme="dark"] .graph-link {
  stroke: var(--line-strong);
}

[data-theme="dark"] .graph-node circle {
  stroke: var(--paper);
}

[data-theme="dark"] .graph-label {
  stroke: var(--halo);
}

[data-theme="dark"] .graph-hover,
[data-theme="dark"] .impact-card,
[data-theme="dark"] .code-panel,
[data-theme="dark"] .code-body,
[data-theme="dark"] .bubble,
[data-theme="dark"] .composer,
[data-theme="dark"] .topic-builder,
[data-theme="dark"] .topic-builder select,
[data-theme="dark"] .flow-form input,
[data-theme="dark"] .loading-bar,
[data-theme="dark"] .toast {
  background: var(--paper);
}

[data-theme="dark"] .bubble.user {
  background: repeating-linear-gradient(
    135deg,
    var(--paper),
    var(--paper) 10px,
    var(--paper-3) 10px,
    var(--paper-3) 12px
  );
}

[data-theme="dark"] .loading-bubble {
  background: repeating-linear-gradient(
    135deg,
    var(--paper),
    var(--paper) 10px,
    var(--paper-3) 10px,
    var(--paper-3) 12px
  );
}

[data-theme="dark"] .loading-bubble::before {
  background: var(--paper);
}

[data-theme="dark"] .loading-bar span {
  background: repeating-linear-gradient(
    135deg,
    var(--yellow),
    var(--yellow) 8px,
    var(--paper-2) 8px,
    var(--paper-2) 16px
  );
}

[data-theme="dark"] .chip,
[data-theme="dark"] .symbol-chip,
[data-theme="dark"] .impact-card p,
[data-theme="dark"] .issue-card p {
  color: var(--ink);
}

[data-theme="dark"] .method {
  background: var(--paper-3);
}

[data-theme="dark"] .kind,
[data-theme="dark"] .severity {
  background: var(--paper-3);
}

[data-theme="dark"] .severity.low {
  background: var(--severity-low);
}

[data-theme="dark"] .flow {
  border-left-color: var(--line-strong);
}

[data-theme="dark"] .code-line .src {
  color: var(--code-text);
}

[data-theme="dark"] .code-line .ln {
  color: var(--faint);
}

[data-theme="dark"] .code-line.in-symbol {
  background: rgba(233, 196, 90, 0.14);
}

[data-theme="dark"] .code-line.hit .src {
  color: var(--on-accent);
}

[data-theme="dark"] .bubble.error,
[data-theme="dark"] .inline-error {
  border-color: #d47268;
  background: #3a211f;
  color: #ffd9d4;
}

[data-theme="dark"] .code-placeholder.error {
  color: #ff9f95;
}

[data-theme="dark"] .spinner {
  border-color: var(--line-strong);
  border-top-color: var(--ink);
}

[data-theme="dark"] .loading-figure {
  filter: drop-shadow(0 3px 0 rgba(0, 0, 0, 0.45));
}

[data-theme="dark"] ::-webkit-scrollbar-thumb {
  background: var(--line-strong);
  border-color: var(--paper);
}

@media (max-width: 720px) {
  .modal-backdrop {
    padding: 12px;
  }
  .example-modal {
    padding: 16px;
  }
  .example-grid {
    grid-template-columns: 1fr;
  }
}

/* ---------- guided demo ---------- */
.demo-button {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 7px 12px;
  border: 2px solid var(--ink);
  border-radius: 10px;
  background: var(--mint);
  color: var(--ink);
  font-size: 13px;
  font-weight: 700;
  box-shadow: 2px 2px 0 -1px var(--ink);
  transition: transform 0.08s ease, box-shadow 0.08s ease, background 0.08s ease;
}

.demo-button:hover {
  background: var(--yellow);
  transform: translate(1px, 1px);
  box-shadow: 1px 1px 0 -1px var(--ink);
}

.demo-button-icon {
  width: 18px;
  height: 18px;
  display: grid;
  place-items: center;
  padding-left: 1px;
  border-radius: 50%;
  background: var(--ink);
  color: var(--paper);
  font-size: 8px;
  line-height: 1;
}

.demo-backdrop {
  z-index: 80;
  padding: 20px;
  background: rgba(20, 20, 22, 0.72);
  backdrop-filter: none;
}

.demo-modal {
  width: min(1120px, 100%);
  height: min(760px, calc(100vh - 40px));
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border: 4px solid var(--ink);
  border-radius: 20px;
  background: var(--paper);
  box-shadow: var(--shadow-lg);
  animation: demo-modal-in 0.28s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

@keyframes demo-modal-in {
  from {
    opacity: 0;
    transform: translateY(14px) scale(0.985);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.demo-top {
  display: flex;
  align-items: center;
  gap: 11px;
  flex: none;
  padding: 12px 18px;
  border-bottom: 2px solid var(--ink);
  background: var(--paper);
}

.demo-top-logo {
  width: 34px;
  height: 34px;
  flex: none;
  display: grid;
  place-items: center;
  border: 2px solid var(--ink);
  border-radius: 10px;
  background: var(--yellow-soft);
  box-shadow: 2px 2px 0 -1px var(--ink);
}

.demo-top-copy {
  display: flex;
  flex-direction: column;
  line-height: 1.16;
}

.demo-top-copy strong {
  font-size: 13px;
}

.demo-top-copy span {
  color: var(--muted);
  font-size: 9.5px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
}

.demo-count {
  margin-left: auto;
  padding: 2px 9px;
  border: 2px solid var(--ink);
  border-radius: 20px;
  background: var(--paper-2);
  font-family: var(--mono);
  font-size: 10.5px;
  white-space: nowrap;
}

.demo-close {
  flex: none;
}

.demo-body {
  flex: 1;
  min-height: 0;
  display: grid;
  place-items: center;
  overflow: auto;
  padding: clamp(20px, 3.6vw, 42px);
  background: var(--paper);
}

.demo-slide {
  width: 100%;
  display: grid;
  grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.1fr);
  gap: clamp(24px, 4vw, 56px);
  align-items: center;
}

.demo-slide.forward {
  animation: demo-slide-forward 0.42s cubic-bezier(0.2, 0.7, 0.2, 1) both;
}

.demo-slide.back {
  animation: demo-slide-back 0.42s cubic-bezier(0.2, 0.7, 0.2, 1) both;
}

@keyframes demo-slide-forward {
  from {
    opacity: 0;
    transform: translateX(30px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes demo-slide-back {
  from {
    opacity: 0;
    transform: translateX(-30px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.demo-copy {
  min-width: 0;
  max-width: 560px;
}

.demo-copy > * {
  animation: demo-rise 0.48s cubic-bezier(0.2, 0.7, 0.2, 1) both;
}

.demo-copy > :nth-child(1) {
  animation-delay: 0.03s;
}
.demo-copy > :nth-child(2) {
  animation-delay: 0.07s;
}
.demo-copy > :nth-child(3) {
  animation-delay: 0.11s;
}
.demo-copy > :nth-child(4) {
  animation-delay: 0.15s;
}
.demo-copy > :nth-child(5) {
  animation-delay: 0.19s;
}
.demo-copy > :nth-child(6) {
  animation-delay: 0.23s;
}

@keyframes demo-rise {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.demo-copy h2 {
  margin: 0 0 14px;
  font-size: clamp(31px, 4.2vw, 52px);
  line-height: 1.02;
  letter-spacing: -0.035em;
}

.demo-body-text {
  margin: 0;
  max-width: 58ch;
  color: var(--muted);
  font-size: 15px;
  line-height: 1.65;
}

.demo-points {
  margin: 20px 0 0;
  padding-left: 22px;
  list-style: disc;
}

.demo-points li {
  margin-top: 8px;
  font-size: 12.5px;
  font-weight: 600;
  line-height: 1.5;
}

.demo-points li:first-child {
  margin-top: 0;
}

.demo-points li::marker {
  color: var(--muted);
}

.demo-try {
  margin-top: 23px;
}

.demo-final-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 9px;
  margin-top: 24px;
}

.demo-final-actions .ghost,
.demo-final-actions .primary {
  box-shadow: var(--shadow-sm);
}

.demo-art {
  position: relative;
  min-height: 380px;
  display: grid;
  place-items: center;
  animation: demo-art-in 0.55s 0.08s cubic-bezier(0.2, 0.7, 0.2, 1) both;
}

@keyframes demo-art-in {
  from {
    opacity: 0;
    transform: scale(0.96) translateY(10px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

/* intro constellation */
.demo-orbit {
  position: relative;
  width: min(100%, 430px);
  aspect-ratio: 1;
  display: grid;
  place-items: center;
}

.demo-orbit-ring {
  position: absolute;
  inset: 9%;
  border: 2px dashed var(--line-strong);
  border-radius: 50%;
}

.demo-orbit-ring.ring-a {
  animation: demo-spin 42s linear infinite;
}

.demo-orbit-ring.ring-b {
  inset: 22%;
  border-style: solid;
  border-color: var(--line);
}

@keyframes demo-spin {
  to {
    transform: rotate(360deg);
  }
}

.demo-orbit-core {
  position: relative;
  z-index: 2;
  width: 158px;
  height: 158px;
  display: grid;
  place-items: center;
  border: 4px solid var(--ink);
  border-radius: 50%;
  background: var(--yellow-soft);
  box-shadow: var(--shadow-lg);
  animation: demo-bob 5s ease-in-out infinite;
}

@keyframes demo-bob {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-6px);
  }
}

.demo-orbit-chip {
  position: absolute;
  z-index: 3;
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 64px;
  padding: 8px 11px;
  border: 2px solid var(--ink);
  border-radius: 12px;
  background: var(--paper);
  box-shadow: var(--shadow-sm);
  animation: demo-bob 5s ease-in-out infinite;
}

.demo-orbit-chip strong {
  font-family: var(--mono);
  font-size: 15px;
  line-height: 1.15;
}

.demo-orbit-chip span {
  color: var(--muted);
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.demo-orbit-chip.one {
  top: 4%;
  left: 10%;
  background: var(--mint);
  animation-delay: -1.2s;
}

.demo-orbit-chip.two {
  top: 16%;
  right: 3%;
  background: var(--blue);
  animation-delay: -2.4s;
}

.demo-orbit-chip.three {
  bottom: 10%;
  left: 4%;
  background: var(--lilac);
  animation-delay: -3.1s;
}

.demo-orbit-chip.four {
  right: 8%;
  bottom: 3%;
  background: var(--salmon);
  animation-delay: -4s;
}

/* source card */
.demo-source {
  position: relative;
  width: min(100%, 440px);
  display: flex;
  flex-direction: column;
  gap: 10px;
  overflow: hidden;
  padding: 16px;
  border: 3px solid var(--ink);
  border-radius: 16px;
  background: var(--paper);
  box-shadow: var(--shadow-lg);
}

.demo-source-head {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.11em;
}

.demo-source-dot {
  width: 8px;
  height: 8px;
  border: 1.5px solid var(--ink);
  border-radius: 50%;
  background: var(--mint);
}

.demo-source-pill {
  margin-left: auto;
  padding: 1px 6px;
  border: 1.5px solid var(--ink);
  border-radius: 20px;
  background: var(--paper-2);
  font-size: 8px;
  letter-spacing: 0.06em;
}

.demo-source-tabs {
  display: inline-flex;
  align-self: flex-start;
  gap: 2px;
  padding: 3px;
  border: 2px solid var(--ink);
  border-radius: 9px;
  background: var(--paper-2);
}

.demo-source-tab {
  padding: 3px 8px;
  border-radius: 5px;
  color: var(--muted);
  font-size: 9.5px;
  font-weight: 600;
}

.demo-source-tab.active {
  border: 1.5px solid var(--ink);
  background: var(--yellow);
  color: var(--on-accent);
}

.demo-source-field {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  padding: 8px 10px;
  border: 2px solid var(--ink);
  border-radius: 9px;
  background: var(--paper-2);
  box-shadow: 2px 2px 0 -1px var(--ink);
  font-family: var(--mono);
  font-size: 10.5px;
}

.demo-prompt {
  color: var(--muted);
}

.demo-path {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.demo-caret {
  width: 2px;
  height: 13px;
  flex: none;
  margin-left: auto;
  background: var(--ink);
}

.demo-source-button {
  align-self: flex-start;
  padding: 5px 12px;
  border: 2px solid var(--ink);
  border-radius: 8px;
  background: var(--yellow);
  color: var(--on-accent);
  box-shadow: 2px 2px 0 -1px var(--ink);
  font-size: 10.5px;
  font-weight: 700;
}

.demo-source-status {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9.5px;
}

.demo-scan-dot {
  width: 7px;
  height: 7px;
  flex: none;
  border-radius: 50%;
  background: var(--ink);
}

.demo-mini-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 7px;
  margin-top: 2px;
}

.demo-mini-stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
  padding: 7px 5px;
  border: 2px solid var(--ink);
  border-radius: 8px;
  background: var(--paper-2);
}

.demo-mini-stat strong {
  font-family: var(--mono);
  font-size: 15px;
  line-height: 1.1;
}

.demo-mini-stat span {
  color: var(--muted);
  font-size: 8.5px;
  text-transform: uppercase;
  letter-spacing: 0.07em;
}

/* map visual */
.demo-map {
  position: relative;
  width: min(100%, 470px);
  aspect-ratio: 1.15;
  overflow: hidden;
  border: 3px solid var(--ink);
  border-radius: 18px;
  background-color: var(--paper);
  background-image: radial-gradient(var(--grid) 1.2px, transparent 1.2px);
  background-size: 18px 18px;
  box-shadow: var(--shadow-lg);
}

.demo-map-lines {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.demo-map-lines path {
  fill: none;
  stroke: var(--line-strong);
  stroke-width: 2;
  stroke-dasharray: 6 5;
}

.demo-bubble {
  position: absolute;
  width: 88px;
  height: 72px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  padding: 8px;
  text-align: center;
  border: 2px solid var(--ink);
  border-radius: 46% 54% 50% 50% / 50% 45% 55% 50%;
  box-shadow: 3px 3px 0 -1px var(--ink);
  animation: demo-pop 0.48s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

.demo-bubble strong {
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: 10px;
  letter-spacing: 0.06em;
}

.demo-bubble small {
  color: var(--muted);
  font-size: 8.5px;
}

@keyframes demo-pop {
  from {
    opacity: 0;
