  let state: "code" | "line" | "block" | "sq" | "dq" | "tpl" = "code";

  const blank = (i: number) => {
    if (i < out.length && out[i] !== "\n") out[i] = " ";
  };

  for (let i = 0; i < src.length; i++) {
    const c = src[i];
    const n = src[i + 1];
    switch (state) {
      case "code":
        if (c === "/" && n === "/") {
          blank(i);
          blank(i + 1);
          i++;
          state = "line";
        } else if (c === "/" && n === "*") {
          blank(i);
          blank(i + 1);
          i++;
          state = "block";
        } else if (hashComments && c === "#") {
          blank(i);
          state = "line";
        } else if (c === '"') {
          if (maskStrings) blank(i);
          state = "dq";
        } else if (c === "'") {
          if (maskStrings) blank(i);
          state = "sq";
        } else if (c === "`") {
          if (maskStrings) blank(i);
          state = "tpl";
        }
        break;
      case "line":
        blank(i);
        if (c === "\n") {
          out[i] = "\n";
          state = "code";
        }
        break;
      case "block":
        blank(i);
        if (c === "*" && n === "/") {
          blank(i + 1);
          i++;
          state = "code";
        }
        break;
      case "dq":
        if (maskStrings) blank(i);
        if (c === "\\") {
          if (maskStrings) blank(i + 1);
          i++;
        } else if (c === '"') {
          if (maskStrings) blank(i);
          state = "code";
        } else if (c === "\n") {
          state = "code";
        }
        break;
      case "sq":
        if (maskStrings) blank(i);
        if (c === "\\") {
          if (maskStrings) blank(i + 1);
          i++;
        } else if (c === "'") {
          if (maskStrings) blank(i);
          state = "code";
        } else if (c === "\n") {
          state = "code";
        }
        break;
      case "tpl":
        if (maskStrings) blank(i);
        if (c === "\\") {
          if (maskStrings) blank(i + 1);
          i++;
        } else if (c === "`") {
          if (maskStrings) blank(i);
          state = "code";
        }
