const pushEndpoint = (endpoint: Endpoint) => {
  // Catch-all mounts are wiring, not API surface.
  if (endpoint.method === "ANY" && (endpoint.path === "/*" || endpoint.path === "/")) return;
  const key = `${endpoint.method} ${endpoint.path}@${endpoint.file}:${endpoint.line}`;
  if (endpointKeys.has(key)) return;
  endpointKeys.add(key);
  endpoints.push(endpoint);
};

function graphFramework(line: string): string {
  if (/\brouter\./.test(line)) return "express/router";
  if (/\bapp\./.test(line)) return "web framework";
  return "http";
}

export async function resolveCommit(root: string, ref: string): Promise<SnapshotCommit> {
  const cleaned = ref.trim();
  if (!cleaned || cleaned.length > 200) {
    throw new Error("A commit reference is required.");
  }

  let sha: string;
  try {
    const { stdout } = await run(
      "git",
      ["-C", root, "rev-parse", "--verify", `${cleaned}^{commit}`],
      { maxBuffer: 1_000_000 },
    );
    sha = stdout.trim();
  } catch {
    throw new Error(`Could not resolve commit "${cleaned}" in this repository.`);
  }

  if (!/^[0-9a-f]{40,64}$/i.test(sha)) {
    throw new Error(`Git returned an invalid commit id for "${cleaned}".`);
  }

  try {
    const { stdout } = await run(
      "git",
      ["-C", root, "show", "-s", "--format=%h%x00%s%x00%ad%x00%an", "--date=short", sha],
      { maxBuffer: 1_000_000 },
    );
    const [short, subject, date, author] = stdout.trimEnd().split("\u0000");
    return {
      sha,
      short: short || sha.slice(0, 7),
      subject: subject || "(no subject)",
      date: date || "",
      author: author || "unknown",
    };
  } catch {
    return { sha, short: sha.slice(0, 7), subject: "(no subject)", date: "", author: "unknown" };
  }
}

async function listTree(root: string, sha: string): Promise<TreeEntry[]> {
  const { stdout } = await run("git", ["-C", root, "ls-tree", "-r", "-z", "-l", sha], {
    maxBuffer: MAX_GIT_OUTPUT,
  });

  const entries: TreeEntry[] = [];
  for (const record of stdout.split("\u0000")) {
    if (!record) continue;
    const tab = record.indexOf("\t");
    if (tab === -1) continue;
    const meta = record.slice(0, tab).trim().split(/\s+/);
    const type = meta[1];
    const oid = meta[2];
    const size = Number(meta[3]);
    const filePath = record.slice(tab + 1);
    if (type !== "blob" || !oid || !filePath) continue;
    if (!Number.isFinite(size) || size < 0) continue;
    entries.push({ path: filePath, oid, size });
  }
  return entries;
}

function readObjects(root: string, oids: string[]): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    const child = spawn("git", ["-C", root, "cat-file", "--batch"], { windowsHide: true });
    const chunks: Buffer[] = [];
    let total = 0;
    let settled = false;
    let stderr = "";

    const fail = (error: Error): void => {
      if (settled) return;
      settled = true;
      child.kill();
      reject(error);
    };

    child.on("error", fail);
    child.stdout?.on("data", (chunk: Buffer) => {
      total += chunk.length;
      if (total > MAX_GIT_OUTPUT) {
        fail(new Error("This commit is too large to read in one analysis."));
        return;
      }
      chunks.push(chunk);
    });
    child.stderr?.on("data", (chunk: Buffer) => {
      stderr += chunk.toString();
    });
    child.on("close", (code) => {
      if (settled) return;
      settled = true;
      if (code !== 0) {
        reject(new Error(stderr.trim() || `git cat-file exited with code ${code}`));
        return;
      }
      resolve(Buffer.concat(chunks));
    });
    child.stdin?.on("error", () => undefined);
    child.stdin?.end(oids.join("\n") + "\n");
  });
}

const fail = (error: Error): void => {
  if (settled) return;
  settled = true;
  child.kill();
  reject(error);
};

async function readContents(root: string, entries: TreeEntry[]): Promise<(string | null)[]> {
  const output = await readObjects(
    root,
    entries.map((entry) => entry.oid),
  );
  const contents: (string | null)[] = [];
  let offset = 0;

  for (const _entry of entries) {
    const newline = output.indexOf(10, offset);
    if (newline === -1) break;
    const header = output.subarray(offset, newline).toString("ascii");
    offset = newline + 1;
    const parts = header.split(" ");
    if (parts[1] === "missing") {
      contents.push(null);
      continue;
    }
    const size = Number(parts[2]);
    if (!Number.isFinite(size) || size < 0 || offset + size > output.length) break;
    const body = output.subarray(offset, offset + size);
    offset += size;
    if (output[offset] === 10) offset += 1;
    contents.push(body.includes(0) ? null : body.toString("utf8"));
  }

  return contents;
}

export function purposeFor(filePath: string): string {
  const normalized = filePath.toLowerCase();
  for (const [re, label] of RULES) {
    if (re.test(normalized)) return label;
  }
  return "supporting application logic";
}

export function purposeTagFor(filePath: string): string {
  const normalized = filePath.toLowerCase();
  for (const [re, label] of TAG_RULES) {
    if (re.test(normalized)) return label;
  }
  return "CORE";
}

function firstSentence(text: string): string {
  const cleaned = text.replace(/\s+/g, " ").trim();
  if (!cleaned) return "";
  const stop = cleaned.search(/[.!?](\s|$)/);
  const sentence = stop > 0 ? cleaned.slice(0, stop + 1) : cleaned;
  return sentence.length > 160 ? sentence.slice(0, 157) + "…" : sentence;
}

export function summarizeFile(input: {
  path: string;
  doc: string;
  loc: number;
  symbols: ParsedSymbol[];
  endpoints: Endpoint[];
  dbOps: DbOp[];
  imports: number;
  external: number;
}): string {
  const purpose = purposeFor(input.path);
  const pieces: string[] = [];
  pieces.push(`Handles ${purpose}.`);

  const doc = firstSentence(input.doc);
  if (doc) pieces.push(doc);

  const names = input.symbols.slice(0, 3).map((s) => s.name);
  if (names.length) {
    const more = input.symbols.length - names.length;
    pieces.push(`Defines ${names.join(", ")}${more > 0 ? ` and ${more} more` : ""}.`);
  }

  if (input.endpoints.length) {
    const list = input.endpoints
      .slice(0, 3)
      .map((e) => `${e.method} ${e.path}`)
      .join(", ");
    pieces.push(
      `Serves ${input.endpoints.length} route${input.endpoints.length === 1 ? "" : "s"} (${list}${
        input.endpoints.length > 3 ? ", …" : ""
      }).`,
    );
  }

  if (input.dbOps.length) {
    pieces.push(
      `Touches the database in ${input.dbOps.length} place${input.dbOps.length === 1 ? "" : "s"}.`,
    );
  }

  if (input.imports === 0 && input.external === 0) {
    pieces.push("Has no imports — likely a leaf module.");
  }

  return pieces.join(" ");
}

export function purposeList(): string[] {
  return RULES.map(([, label]) => label);
}

export function detectLang(filePath: string): Lang {
  const ext = path.extname(filePath).toLowerCase();
  switch (ext) {
    case ".ts":
    case ".mts":
    case ".cts":
      return "ts";
    case ".tsx":
      return "tsx";
    case ".js":
    case ".mjs":
    case ".cjs":
      return "js";
    case ".jsx":
      return "jsx";
    case ".py":
      return "py";
    case ".go":
      return "go";
    case ".java":
    case ".kt":
      return "java";
    case ".rb":
      return "rb";
    case ".rs":
      return "rs";
    case ".hs":
    case ".lhs":
    case ".hsc":
      return "hs";
    case ".css":
    case ".scss":
    case ".less":
      return "css";
    case ".html":
    case ".htm":
      return "html";
    case ".json":
      return "json";
    case ".md":
    case ".mdx":
      return "md";
    case ".sql":
      return "sql";
    case ".yml":
    case ".yaml":
      return "yaml";
    default:
      return "other";
  }
}

export function isCodeLang(lang: Lang): boolean {
  return ["ts", "tsx", "js", "jsx", "py", "go", "java", "rb", "rs", "hs"].includes(lang);
}

export function toPosix(p: string): string {
  return p.split(path.sep).join("/");
}

export function isIgnoredRepoPath(filePath: string): boolean {
  const parts = filePath.split("/");
  for (let i = 0; i < parts.length - 1; i++) {
    if (parts[i].startsWith(".") || IGNORED_DIRS.has(parts[i])) return true;
  }
  return IGNORED_FILE.test(filePath);
}

async function visit(dir: string): Promise<void> {
  if (files.length >= limit) {
    truncated = true;
    return;
  }
  let entries: import("node:fs").Dirent[];
  try {
    entries = await fs.readdir(dir, { withFileTypes: true });
  } catch {
    return;
  }
  entries.sort((a, b) => a.name.localeCompare(b.name));
  for (const entry of entries) {
    if (files.length >= limit) {
      truncated = true;
      return;
    }
    const abs = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      if (entry.name.startsWith(".")) continue;
      if (IGNORED_DIRS.has(entry.name)) continue;
      await visit(abs);
      continue;
    }
    if (!entry.isFile() || IGNORED_FILE.test(abs)) continue;
    const rel = toPosix(path.relative(resolved, abs));
    const lang = detectLang(rel);
    if (lang === "other") continue;
    const info = await fs.stat(abs).catch(() => null);
    if (!info || info.size > MAX_FILE_BYTES) continue;
    const content = await fs.readFile(abs, "utf8").catch(() => null);
    if (content === null || content.includes("\u0000")) continue;
    files.push({ path: rel, content, lang, size: info.size });
  }
}

function escapeText(text: string): string {
