function smallTalkAnswer(rec: RepoRecord, question: string): AskResponse | null {
  const n = normalizeQuestion(question);
  const words = n.split(" ").filter(Boolean);
  if (!n) return null;

  const { stats } = rec.analysis;
  const label = rec.analysis.source.label;
  const entry = rec.analysis.entryPoints[0];

  if (
    words.length <= 4 &&
    /^(hi|hey|hello|yo|hiya|howdy|sup|greetings|good morning|good afternoon|good evening|hola)( there| everyone| all| again)?$/.test(
      n,
    )
  ) {
    const opener = pick([
      `Hey — I've mapped **${label}**: ${stats.files} files, ${stats.symbols} symbols and ${stats.endpoints} routes.`,
      `Hello. **${label}** is loaded — ${stats.files} files and ${stats.loc.toLocaleString()} lines of source.`,
      `Hi. I'm holding the map of **${label}** (${stats.symbols} parsed symbols, ${stats.endpoints} routes).`,
    ]);
    return plain(
      `${opener} Ask me where a behaviour lives, how a request moves through the code, or what would break if you changed a function.` +
        (entry ? ` If you want a thread to pull, \`${entry}\` is where the app starts.` : ""),
    );
  }

  if (
    words.length <= 6 &&
    /^(thanks|thank you|thanks a lot|thank you so much|thx|ty|cheers|appreciate it|appreciated|nice one|great|awesome|cool)( so much| a lot| very much| for that| that helps| that helped)?$/.test(
      n,
    )
  ) {
    return plain(
      pick([
        "Anytime. If another part of the codebase is still a mystery, name a file or a behaviour and I'll trace it.",
        `You're welcome. I still have the map of ${label} loaded, so keep the questions coming.`,
        "Glad that helped. Ask about another module and I'll pull the relevant files and call edges.",
      ]),
    );
  }

  if (words.length <= 4 && /^(bye|goodbye|see you|see ya|later|ciao|good night)( for now| then)?$/.test(n)) {
    return plain("See you. The analysis stays loaded for this session if you come back with more questions.");
  }

  if (
    /^(who are you|what are you|what can you do|what do you do|how do i use (this|you)|what is this( app| tool)?|help|help me)$/.test(
      n,
    )
  ) {
    return plain(
      `I'm the reading guide for **${label}** — I parse the source, resolve imports and infer call edges, then answer from what is actually on disk. ` +
        `Right now I'm looking at ${stats.files} files, ${stats.symbols} symbols and ${stats.endpoints} routes.\n\n` +
        "- **Where does X live?** — name a behaviour and I'll point at the file and line.\n" +
        "- **How does X work?** — name a route or function and I'll lay out the call path.\n" +
        "- **What breaks if I change X?** — I'll show callers, affected files and touched endpoints.\n\n" +
        (llmConfigured()
          ? "Answers are written by the configured language model and constrained to retrieved source."
          : "I'm running the deterministic engine: answers are assembled from retrieved code, with no model guessing, and every claim carries a `file:line`."),
    );
  }

  return null;
}

function overviewAnswer(rec: RepoRecord): AskResponse {
  const { stats, files, entryPoints, source } = rec.analysis;
  const { citations, cite } = makeCiter(rec);
  const lines: string[] = [];

  const languages = [...stats.languages]
    .sort((a, b) => b.loc - a.loc)
    .slice(0, 3)
    .map(
      (l) =>
        `${languageName(l.lang)} (${l.loc.toLocaleString()} lines across ${l.files} file${
          l.files === 1 ? "" : "s"
        })`,
    );

  lines.push(
    `**${source.label}** is ${stats.files} files and ${stats.loc.toLocaleString()} lines, holding ${stats.symbols} symbols and ${stats.endpoints} HTTP route${
      stats.endpoints === 1 ? "" : "s"
    }.`,
  );
  if (languages.length) lines.push(`Most of it is ${languages.join(", ")}.`);
  if (stats.gitAvailable && stats.commits) {
    const contributor = stats.contributors[0];
    lines.push(
      `Git history covers ${stats.commits} commit${stats.commits === 1 ? "" : "s"}${
        contributor ? `, most recently from ${contributor.name}` : ""
      }.`,
    );
  }

  const entries = entryPoints.slice(0, 3).flatMap((entry) => {
    const file = files.find((candidate) => candidate.path === entry);
    return file ? [file] : [];
  });
  if (entries.length) {
    lines.push("\n**Start here**");
    for (const file of entries) {
      lines.push(`- \`${file.path}\` — ${file.summary} ${cite(file.path, 1)}`);
    }
  }

  const largest = files
    .filter((file) => file.presence === "code")
    .sort((a, b) => b.loc - a.loc)
    .slice(0, 3);
  if (largest.length) {
    lines.push("\n**Largest modules**");
    for (const file of largest) {
      lines.push(`- \`${file.path}\` — ${file.loc} lines, ${file.symbols.length} symbols ${cite(file.path, 1)}`);
    }
  }

  return {
    answer: lines.join("\n"),
    citations: citations.slice(0, 12),
    mode: "local",
    topFiles: entries.map((file) => file.path),
  };
}

function languageName(lang: string): string {
  const names: Record<string, string> = {
    ts: "TypeScript",
    tsx: "TSX",
    js: "JavaScript",
    jsx: "JSX",
    py: "Python",
    go: "Go",
    java: "Java",
    rb: "Ruby",
    rs: "Rust",
    css: "CSS",
    html: "HTML",
    json: "JSON",
    md: "Markdown",
    sql: "SQL",
    yaml: "YAML",
  };
  return names[lang] ?? lang.toUpperCase();
}

function buildBubbleContext(rec: RepoRecord, bubble: Bubble): string {
  const { files, symbols } = bubbleMembers(rec, bubble);
  const loc = files.reduce((sum, file) => sum + file.loc, 0);
  return buildContext(
    rec,
    files,
    symbols.slice(0, 10).map((symbol) => symbol.name),
    {
      maxFiles: 8,
      lead: [
        `Purpose bubble: ${bubble.purpose} — ${files.length} files, ${loc.toLocaleString()} lines.`,
        `All files below belong to the ${bubble.purpose} purpose bubble. Treat a question about this bubble as a question about the entire group, not a single symbol or file.`,
        `Bubble members: ${files.map((file) => file.path).join(", ")}`,
      ],
    },
  );
}

function extractCitations(text: string, rec: RepoRecord): Citation[] {
  const citations: Citation[] = [];
  const seen = new Set<string>();
  // Models cite single lines, ranges (14-22) and several locations inside one
  // bracket ([a.ts:3, b.ts:9]); scan pairs instead of one bracket-shaped match.
  const re = /([A-Za-z0-9_./@()+-]+\.[A-Za-z0-9]+):(\d+)(?:\s*[-–]\s*(\d+))?/g;
  let match: RegExpExecArray | null;
  while ((match = re.exec(text))) {
    const file = match[1].replace(/^\.\//, "");
    const line = Number(match[2]);
    if (!Number.isFinite(line) || !rec.contents.has(file)) continue;
    const key = `${file}:${line}`;
    if (seen.has(key)) continue;
    seen.add(key);
    citations.push({
      file,
      line,
      endLine: match[3] ? Number(match[3]) : undefined,
      label: `${file}:${line}`,
    });
  }
  return citations.slice(0, 12);
}

function push(map: Map<string, string[]>, key: string, value: string): void {
  const bucket = map.get(key) ?? [];
  if (!bucket.includes(value)) bucket.push(value);
  map.set(key, bucket);
}

function allEndpoints(analysis: Analysis): Endpoint[] {
  return analysis.files.flatMap((f) => f.endpoints);
}

export function buildFlow(rec: RepoRecord, options: FlowOptions): FlowResponse {
  const { analysis } = rec;
  const symbolById = new Map(analysis.symbols.map((s) => [s.id, s]));
  const callees = new Map<string, string[]>();
  for (const edge of analysis.callEdges) push(callees, edge.from, edge.to);

  let endpoint: Endpoint | undefined;
  let seed: RepoSymbol | undefined;
  let confidence = 0.5;
  const question = options.query?.trim() || "the execution flow";

  if (options.symbolId) {
    seed = symbolById.get(options.symbolId);
    confidence = 0.78;
  }

  if (!seed && options.endpoint) {
    endpoint = allEndpoints(analysis).find(
      (e) =>
        e.file === options.endpoint!.file &&
        e.method === options.endpoint!.method &&
        e.path === options.endpoint!.path,
    );
  }

  if (!seed && !endpoint && options.query) {
    const tokens = expandTokens(tokenize(options.query));
    const ranked = rankEndpoints(rec, tokens);
    if (ranked.length && ranked[0].score >= 8) {
      endpoint = ranked[0].endpoint;
      confidence = 0.8;
    } else {
      // No route matched: pick the best symbol by call context as well.
      const candidates = analysis.symbols
        .map((symbol) => {
          const nameTokens = tokenize(symbol.name);
          let score = 0;
          for (const token of tokens) {
            if (nameTokens.includes(token)) score += 8;
            else if (symbol.name.toLowerCase().includes(token) && token.length > 3) score += 2;
          }
          if (analysis.callEdges.some((e) => e.from === symbol.id)) score += 1;
          return { symbol, score };
        })
        .filter((c) => c.score > 0)
        .sort((a, b) => b.score - a.score);
      if (candidates.length) {
        seed = candidates[0].symbol;
        confidence = 0.62;
      }
    }
  }

  if (!seed && endpoint) {
    const handler = endpoint.handler ? symbolById.get(endpoint.handler) : undefined;
    if (handler) {
      seed = handler;
    } else {
      const inFile = analysis.symbols
        .filter((s) => s.file === endpoint!.file && s.kind !== "class")
        .sort((a, b) => Math.abs(a.line - endpoint!.line) - Math.abs(b.line - endpoint!.line));
      seed = inFile[0];
    }
  }

  const steps: FlowStep[] = [];
  if (endpoint) {
    steps.push({
      name: `${endpoint.method} ${endpoint.path}`,
      file: endpoint.file,
      line: endpoint.line,
      kind: "endpoint",
      depth: 0,
      note: `HTTP ${endpoint.method} route (${endpoint.framework})`,
    });
  }

  const visited = new Set<string>();
  const isInlineHandler = Boolean(
    endpoint && seed && seed.name === `${endpoint.method} ${endpoint.path}`,
  );
  const queue: { id: string; depth: number; via?: string }[] = [];
  if (seed) {
    if (isInlineHandler) {
      // The synthetic route handler is the endpoint step; start at what it calls.
      visited.add(seed.id);
      for (const next of callees.get(seed.id) ?? []) {
        queue.push({ id: next, depth: 1, via: "the route handler" });
      }
    } else {
      queue.push({ id: seed.id, depth: endpoint ? 1 : 0 });
    }
  }

  while (queue.length && steps.length < 15) {
    const item = queue.shift()!;
    if (visited.has(item.id)) continue;
    visited.add(item.id);
    const symbol = symbolById.get(item.id);
    if (!symbol) continue;
    steps.push({
      symbolId: symbol.id,
      name: symbol.name,
      file: symbol.file,
      line: symbol.line,
      kind: symbol.kind,
      depth: item.depth,
      note: item.via
        ? `called by ${item.via}`
        : endpoint
          ? `handles ${endpoint.method} ${endpoint.path}`
          : `${symbol.kind} entry point`,
    });
    if (item.depth >= 4) continue;
    for (const next of callees.get(item.id) ?? []) {
      if (!visited.has(next)) queue.push({ id: next, depth: item.depth + 1, via: symbol.name });
    }
  }

export function buildImpact(rec: RepoRecord, symbolId: string): ImpactResponse {
  const { analysis } = rec;
  const symbol = analysis.symbols.find((s) => s.id === symbolId) ?? null;
  if (!symbol) {
    return {
      symbol: null,
      affectedSymbols: [],
      affectedFiles: [],
      endpoints: [],
      tests: [],
      summary: "No symbol selected. Open a file and place the cursor on a function to run a blast-radius analysis.",
    };
  }

  const callers = new Map<string, string[]>();
  for (const edge of analysis.callEdges) push(callers, edge.to, edge.from);

  const symbolById = new Map(analysis.symbols.map((s) => [s.id, s]));
  const affected = new Map<string, RepoSymbol>();
  const queue: { id: string; depth: number }[] = [{ id: symbol.id, depth: 0 }];
  const seen = new Set<string>([symbol.id]);

  while (queue.length) {
    const item = queue.shift()!;
    if (item.depth >= 6) continue;
    for (const callerId of callers.get(item.id) ?? []) {
      if (seen.has(callerId)) continue;
      seen.add(callerId);
      const caller = symbolById.get(callerId);
      if (!caller) continue;
      affected.set(caller.id, caller);
      queue.push({ id: caller.id, depth: item.depth + 1 });
    }
  }

  const affectedSymbols = [...affected.values()];
  const affectedFiles = [...new Set([symbol.file, ...affectedSymbols.map((s) => s.file)])];

  const endpointSet = new Map<string, Endpoint>();
  for (const file of analysis.files) {
    if (!affectedFiles.includes(file.path)) continue;
    for (const endpoint of file.endpoints) {
      endpointSet.set(`${endpoint.method} ${endpoint.path}`, endpoint);
    }
  }

  const tests = affectedFiles.filter(isTestFile);
  const endpoints = [...endpointSet.values()];

  const summary =
    `Changing \`${symbol.name}\` can reach ${affectedSymbols.length} other symbol${
      affectedSymbols.length === 1 ? "" : "s"
    } across ${affectedFiles.length} file${affectedFiles.length === 1 ? "" : "s"}` +
    (endpoints.length ? ` and ${endpoints.length} endpoint${endpoints.length === 1 ? "" : "s"}` : "") +
    "." +
    (tests.length
      ? ` ${tests.length} test file${tests.length === 1 ? "" : "s"} sit in the affected area.`
      : " No test files were found anywhere in the affected area.");

  return {
    symbol,
    affectedSymbols,
    affectedFiles,
    endpoints,
    tests,
    summary,
  };
}

function parseHistory(raw: unknown): AskHistoryMessage[] {
  if (!Array.isArray(raw)) return [];
  const history: AskHistoryMessage[] = [];
  for (const item of raw) {
    if (!item || typeof item !== "object") continue;
    const candidate = item as { role?: unknown; text?: unknown };
    if (candidate.role !== "user" && candidate.role !== "assistant") continue;
    if (typeof candidate.text !== "string") continue;
    const text = candidate.text.trim().slice(0, 2000);
    if (!text) continue;
    history.push({ role: candidate.role, text });
  }
  return history.slice(-8);
}

function errorMessage(error: unknown): string {
  if (error instanceof Error) return error.message;
  return String(error);
}

app.post("/api/analyze", async (c) => {
  try {
    const body = (await c.req.json()) as {
      source?: "local" | "github";
      path?: string;
      url?: string;
      ref?: string;
    };
    const source = body.source === "github" ? "github" : "local";
    const result = await analyzeRepository({
      source,
      path: body.path,
      url: body.url,
      ref: typeof body.ref === "string" ? body.ref.trim().slice(0, 200) : undefined,
    });
    putRepo(result);
    return c.json({ analysis: result.analysis });
  } catch (error) {
    return c.json({ error: errorMessage(error) }, 400);
  }
});

app.get("/api/repos/:id/file", (c) => {
  try {
    const repo = requireRepo(c.req.param("id"));
    const filePath = c.req.query("path");
    if (!filePath) return c.json({ error: "A ?path= query parameter is required." }, 400);
    const content = repo.contents.get(filePath);
    const meta = repo.analysis.files.find((f) => f.path === filePath);
    if (content === undefined || !meta) return c.json({ error: `File not in analysis: ${filePath}` }, 404);
    return c.json({ path: filePath, lang: meta.lang, content });
  } catch (error) {
    return c.json({ error: errorMessage(error) }, 404);
  }
});

app.post("/api/ask", async (c) => {
  try {
    const body = (await c.req.json()) as {
      repo?: string;
      question?: string;
      history?: unknown;
    };
    const repo = requireRepo(body.repo);
    const question = (body.question ?? "").trim();
    if (!question) return c.json({ error: "Ask a question about the repository." }, 400);
    const result = await answerQuestion(repo, question, parseHistory(body.history));
    return c.json(result);
  } catch (error) {
    return c.json({ error: errorMessage(error) }, 400);
  }
});

app.post("/api/flow", async (c) => {
  try {
    const body = (await c.req.json()) as {
      repo?: string;
