function env(name: string): string | undefined {
  return typeof process !== "undefined" ? process.env[name] : undefined;
}

export function llmProvider(): LlmProvider | null {
  if (env("OPENAI_API_KEY")) return "openai";
  if (env("GEMINI_API_KEY")) return "gemini";
  return null;
}

export function llmConfigured(): boolean {
  return llmProvider() !== null;
}

export function llmModel(): string {
  if (env("OPENAI_MODEL")) return env("OPENAI_MODEL")!;
  return llmProvider() === "gemini" ? GEMINI_DEFAULT_MODEL : "gpt-4o-mini";
}

async function llmComplete(messages: LlmMessage[], maxTokens: number): Promise<string | null> {
  const provider = llmProvider();
  if (!provider) return null;

  const key = provider === "gemini" ? env("GEMINI_API_KEY") : env("OPENAI_API_KEY");
  if (!key) return null;

  const defaultBase = provider === "gemini" ? GEMINI_BASE_URL : "https://api.openai.com/v1";
  const baseUrl = (env("OPENAI_BASE_URL") ?? defaultBase).replace(/\/+$/, "");
  const model = llmModel();

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 45_000);

  try {
    const res = await fetch(`${baseUrl}/chat/completions`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${key}`,
      },
      body: JSON.stringify({
        model,
        temperature: 0.2,
        max_tokens: maxTokens,
        messages,
      }),
      signal: controller.signal,
    });

    if (!res.ok) {
      const detail = (await res.text()).slice(0, 300);
      console.warn(`[llm] ${provider} ${res.status} ${res.statusText}: ${detail}`);
      return null;
    }
    const data = (await res.json()) as {
      choices?: { message?: { content?: string } }[];
    };
    const content = data.choices?.[0]?.message?.content;
    return content?.trim() ? content.trim() : null;
  } catch (error) {
    const message = error instanceof Error ? `${error.name}: ${error.message}` : String(error);
    console.warn(`[llm] ${provider} request failed: ${message}`);
    return null;
  } finally {
    clearTimeout(timer);
  }
}

export function tokenize(text: string): string[] {
  return text
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter((t) => t.length > 1 && !STOP.has(t));
}

export function expandTokens(tokens: string[]): string[] {
  const out = new Set(tokens);
  for (const token of tokens) {
    // Light stemming so "parsing"/"parsed"/"scans" reach "parse"/"scan"
    // without pulling in a stemmer dependency.
    const base = token.endsWith("ing")
      ? token.slice(0, -3)
      : token.endsWith("ed")
        ? token.slice(0, -2)
        : token.endsWith("s")
          ? token.slice(0, -1)
          : token;
    if (base.length > 3) out.add(base);
    if (base.length > 2) out.add(`${base}e`);
    for (const synonym of SYNONYMS[token] ?? []) out.add(synonym);
    for (const [key, values] of Object.entries(SYNONYMS)) {
      if (values.includes(token) && token.length > 3) out.add(key);
    }
  }
  return [...out];
}

export function rankFiles(rec: RepoRecord, tokens: string[]): RankedFile[] {
  const ranked: RankedFile[] = [];
  for (const file of rec.analysis.files) {
    const pathText = file.path.toLowerCase();
    const pathTokens = new Set(tokenize(file.path));
    let score = 0;
    const purpose = file.purpose.toLowerCase();
    for (const token of tokens) {
      if (pathTokens.has(token)) score += 6;
      else if (pathText.includes(token)) score += 2;
      if (purpose === token) score += 8;
      if (file.summary.toLowerCase().includes(token)) score += 1.4;
      if (file.endpoints.some((e) => e.path.toLowerCase().includes(token))) score += 2.5;
    }
    if (score > 0) {
      score += Math.min(file.endpoints.length, 4);
      ranked.push({ file, score });
    }
  }
  return ranked.sort((a, b) => b.score - a.score || b.file.loc - a.file.loc);
}

export function rankSymbols(rec: RepoRecord, tokens: string[]): RankedSymbol[] {
  const fileByPath = new Map(rec.analysis.files.map((f) => [f.path, f]));
  const ranked: RankedSymbol[] = [];

  for (const symbol of rec.analysis.symbols) {
    const nameTokens = new Set(tokenize(symbol.name));
    const lhs = symbol.name.toLowerCase();
    let score = 0;
    for (const token of tokens) {
      if (lhs === token) score += 12;
      if (nameTokens.has(token)) score += 7;
      else if (lhs.includes(token) && token.length > 3) score += 2.5;
    }
    const body = rec.parsed.get(symbol.file)?.symbols.find((s) => s.id === symbol.id)?.body ?? "";
    const bodyLower = body.toLowerCase();
    for (const token of tokens.slice(0, 10)) {
      let occurrences = 0;
      let idx = bodyLower.indexOf(token);
      while (idx !== -1 && occurrences < 4) {
        occurrences++;
        idx = bodyLower.indexOf(token, idx + token.length);
      }
      score += occurrences * 1.2;
    }
    if (score > 0) ranked.push({ symbol, file: fileByPath.get(symbol.file), score });
  }

  return ranked.sort((a, b) => b.score - a.score);
}

export function rankEndpoints(rec: RepoRecord, tokens: string[]): RankedEndpoint[] {
  const ranked: RankedEndpoint[] = [];
  for (const file of rec.analysis.files) {
    for (const endpoint of file.endpoints) {
      const pathTokens = new Set(tokenize(endpoint.path));
      let score = 0;
      for (const token of tokens) {
        if (pathTokens.has(token)) score += 8;
        else if (endpoint.path.toLowerCase().includes(token)) score += 3;
      }
      if (score > 0) ranked.push({ endpoint, score });
    }
  }
  return ranked.sort((a, b) => b.score - a.score);
}

export function callersOf(rec: RepoRecord, symbolId: string): RepoSymbol[] {
  const ids = new Set(rec.analysis.callEdges.filter((e) => e.to === symbolId).map((e) => e.from));
  return rec.analysis.symbols.filter((s) => ids.has(s.id));
}

export function calleesOf(rec: RepoRecord, symbolId: string): RepoSymbol[] {
  const ids = new Set(rec.analysis.callEdges.filter((e) => e.from === symbolId).map((e) => e.to));
  return rec.analysis.symbols.filter((s) => ids.has(s.id));
}

export function endpointForSymbol(rec: RepoRecord, symbol: RepoSymbol): Endpoint | undefined {
  for (const file of rec.analysis.files) {
    for (const endpoint of file.endpoints) {
      if (endpoint.handler === symbol.id) return endpoint;
    }
  }
  return undefined;
}

export function putRepo(record: RepoRecord): RepoRecord {
  repos.set(record.analysis.id, record);
  while (repos.size > MAX_REPOS) {
    const oldest = repos.keys().next().value;
    if (!oldest) break;
    repos.delete(oldest);
  }
  return record;
}

export function getRepo(id: string | undefined): RepoRecord | undefined {
  if (!id) return undefined;
  return repos.get(id);
}

export function requireRepo(id: string | undefined): RepoRecord {
  const repo = getRepo(id);
  if (!repo) {
    throw new Error("Repository analysis not found. Analyze a repository first (the server keeps the last few analyses in memory).");
  }
  return repo;
}

export function isTestFile(filePath: string): boolean {
  return (
    /(^|\/)(tests?|__tests__|spec|e2e)\//i.test(filePath) ||
    /\.(test|spec)\.[a-z]+$/i.test(filePath) ||
    /(^|\/)(test_|conftest\.py)/i.test(filePath)
  );
}

function staticApi() {
  return import("./staticApi");
}

async function request<T>(url: string, init?: RequestInit): Promise<T> {
  const res = await fetch(url, {
    ...init,
    headers: { "Content-Type": "application/json", ...(init?.headers ?? {}) },
  });
  const data = (await res.json().catch(() => null)) as { error?: string } | null;
  if (!res.ok) {
    throw new Error(data?.error ?? `Request failed (${res.status})`);
  }
  return data as T;
}

export function analyzeRepo(input: {
  source: "local" | "github";
  path?: string;
  url?: string;
  ref?: string;
}): Promise<{ analysis: Analysis }> {
  if (isStaticDemo) {
    return staticApi().then((api) => api.analyzeStaticRepo(input));
  }
  return request("/api/analyze", { method: "POST", body: JSON.stringify(input) });
}

export function fetchFile(repo: string, filePath: string): Promise<FileResponse> {
  if (isStaticDemo) {
    return staticApi().then((api) => api.staticFetchFile(repo, filePath));
  }
  return request(
    `/api/repos/${encodeURIComponent(repo)}/file?path=${encodeURIComponent(filePath)}`,
  );
}

export function analyzeImpact(repo: string, symbolId: string): Promise<ImpactResponse> {
  if (isStaticDemo) {
    return staticApi().then((api) => api.staticAnalyzeImpact(repo, symbolId));
  }
  return request("/api/impact", { method: "POST", body: JSON.stringify({ repo, symbolId }) });
}

export function getConfig(): Promise<{ llm: boolean; model: string }> {
  if (isStaticDemo) {
    return staticApi().then((api) => api.staticConfig());
  }
  return request("/api/config");
}

function initialTheme(): Theme {
  try {
    const saved = window.localStorage.getItem("ca-theme");
    if (saved === "light" || saved === "dark") return saved;
  } catch {
    // Storage can be unavailable; fall through to the OS preference.
  }
  return window.matchMedia?.("(prefers-color-scheme: dark)").matches ? "dark" : "light";
}

