async function run(nextQuery: string, symbolId?: string) {
  if (!nextQuery.trim() && !symbolId) return;
  setBusy(true);
  setError(null);
  try {
    const result = await traceFlow(analysis.id, symbolId ? { symbolId } : { query: nextQuery });
